      'PROCEED WITH CAUTION',
    ],
    [
      // Level 5
      'WE ARE DEEP INTO ALIEN TERRITORY',
      'HIGH ALERT',
    ],
    [
      // Level 6
      'EVIDENCE OF COMPLEX CIVILIZATION',
      'DO NOT UNDERESTIMATE THE ENEMY',
    ],
    [
      // Level 7
      'ALIEN DEFENSES ARRIVED',
      'WATCH OUT FOR MISSILES',
    ],
    [
