    ],
  ],
  [
    [
      // Level failed
      'OH NO!',
      'TRY AGAIN!',
    ],
  ],
];

/**
 * @typedef {{
  *            callback:!Function
  *          }}
  */
let Menu;

/**
 * Level intro screen.
 * Show current level and player details.
 * @return {!Menu}
 */
const levelIntro = () => ({
  callback: () => {
    gameState = GameState.PLAYING;
    gameTime = 0;
    setMenu(null);
  },
});

/**
 * Death screen.
 * Show a sad message.
 * @const {!Menu}
 */
const deathScreen = {
  callback: () => {
    gameState = GameState.BEFORE_LEVEL;
    showLevelIntro();
  },
};

/**
 * Win screen.
 * Show a happy message.
 * @const {!Menu}
 */
const winScreen = {
  callback: () => {
    gameState = GameState.BEFORE_LEVEL;
    setLevel(level + 1);
    showLevelIntro();
  },
};

/**
 * Opening screen to get player input.
 * @const {!Menu}
 */
const clickToStart = {
  callback: () => {
    if (gameState === 0) {
      zzfxX.resume();
