  function nearestEntity(EntityClass) {
    let nearest = null;
    entities.forEach((entity) => {
      if (!(entity instanceof EntityClass) || entity.health <= 0) return;
      const distance = vec3.distance(player.pos, entity.pos);
      if (!nearest || distance < nearest.distance) {
        nearest = {
          x: entity.pos[0],
          y: entity.pos[1],
          z: entity.pos[2],
          distance: distance,
        };
      }
    });
    return nearest;
  }

  function startLevel(requestedLevel) {
    const nextLevel = Math.max(1, Math.min(10, Number(requestedLevel) || 6));
    setLevel(nextLevel);
    gameState = GameState.PLAYING;
    resetLevelCompletion();
    initGame();
    gameTime = 0;
    setMenu(null);
    resetKeys();
    terminalEvent = null;
    episodeCount++;
    return nextLevel;
