      const completed = gameState === GameState.AFTER_LEVEL || terminalEvent !== null;
      const reportedCoins = terminalEvent ? terminalEvent['coins'] : coins;
      const reportedTotal = terminalEvent ? terminalEvent['coinsTotal'] : availableCoins;
      return {
        schemaVersion: '1.0',
        gameId: GAME_ID,
        seed: 47,
