function sampleControlFrame() {
  const movementActive =
      isKeyDown(KEY_UP) || isKeyDown(KEY_W) ||
      isKeyDown(KEY_DOWN) || isKeyDown(KEY_S) ||
      isKeyDown(KEY_LEFT) || isKeyDown(KEY_A) ||
