 * Wait one second before accepting continue button.
 * @type {number}
 */
let menuStartTime = 0;

/**
 * Currently active menu.
 * Start with the intro menu.
 * @type {?Menu}
 */
let menu = clickToStart;

/** @type {?Object} */
let pendingLevelCompletion = null;

/** @type {number} */
let nextLevelCompletionTicket = 0;

/**
 * Opens the success presentation before committing the level transition.
 * @param {!Object} detail
 * @return {number}
 */
function beginLevelCompletion(detail) {
  if (pendingLevelCompletion) {
    return pendingLevelCompletion['ticket'];
  }
  pendingLevelCompletion = {
    ticket: ++nextLevelCompletionTicket,
    detail: detail,
    controlRevision: getControlFrameRevision(),
    age: 0,
  };
  stopJetpackSound();
  setMenu(winScreen);
  return pendingLevelCompletion['ticket'];
}

/**
 * Settles a staged level transition after the presentation has rendered.
 * @param {number} ticket
 * @param {boolean} eligible
 * @return {number} -1 for cancelled, 0 for pending, 1 for committed
 */
function resolveLevelCompletion(ticket, eligible) {
  if (!pendingLevelCompletion ||
      pendingLevelCompletion['ticket'] !== ticket) {
    return -1;
  }
  pendingLevelCompletion['age']++;
  if (pendingLevelCompletion['age'] < 4) {
    return 0;
  }
  if (!eligible ||
      pendingLevelCompletion['controlRevision'] !== getControlFrameRevision()) {
    pendingLevelCompletion = null;
    setMenu(null);
    return -1;
  }
  const detail = pendingLevelCompletion['detail'];
  pendingLevelCompletion = null;
  gameState = GameState.AFTER_LEVEL;
  window.dispatchEvent(new CustomEvent('captaincallisto-level-complete', {
    detail: detail,
  }));
  return 1;
}

/**
 * @return {boolean}
 */
function isLevelCompletionPending() {
  return pendingLevelCompletion !== null;
}

/** Clears staged completion state for a fresh episode. */
function resetLevelCompletion() {
  pendingLevelCompletion = null;
}

/**
 * @return {?Object}
 */
function getLevelCompletionDebug() {
  if (!pendingLevelCompletion) {
    return null;
  }
  return {
    ticket: pendingLevelCompletion['ticket'],
    age: pendingLevelCompletion['age'],
    control_revision: pendingLevelCompletion['controlRevision'],
    current_control_revision: getControlFrameRevision(),
  };
}

