      gameState = GameState.BEFORE_LEVEL;
      setLevel(menuY + 1);
      showLevelIntro();
      playMenuBeep();
    }
    return;
  }

  const completionMenuReady =
      menu === winScreen &&
      (isLevelCompletionPending() || gameState === GameState.AFTER_LEVEL);
  const canContinue = completionMenuReady || time - menuStartTime > 0.5;
  if (canContinue && anyKey.upCount === 1) {
    menu.callback();
  } else {
    if (gameState === GameState.WAITING_FOR_FIRST_CLICK) {
      setTextAlign(ALIGN_CENTER);
      setFontSize(32, 'italic');
      drawShadowText('PRESS ANY KEY TO CONTINUE', CENTER_X, HEIGHT - 90);
