          jetpack_player_cycle: player.jetpackCycle,
          jetpack_thrusting: player.jetpackThrusting,
        },
      };
    },
  };

  const query = new URLSearchParams(window.location.search);
  if (query.get('benchmark') === '1') {
    startLevel(query.get('level') || 6);
  }
})();

/**
 * Flag to control whether keyboard inputs are enabled.
 * @const {boolean}
 */
const KEYBOARD_ENABLED = true;

const KEY_COUNT = 256;
const KEY_ENTER = 13;
const KEY_SHIFT = 16;
const KEY_ESCAPE = 27;
const KEY_SPACE = 32;
const KEY_LEFT = 37;
